# v2 → v3 遷移：33 個細標籤併成 14 個統一標籤（證據沿用 v2 標註時找到的原文片段）。
# 產業類標籤（finance、esg、hr、客服…）不屬於「技能」，不保留；數位轉型例外，因為求職網站把它當技能詞。
V2_TO_V3 = {
    "llm": "LLM", "rag": "RAG", "knowledge_management": "RAG", "ai_agent": "AI Agent",
    "automation": "自動化", "analytics": "數據分析",
    "data_governance": "資料・系統整合", "data_pipeline": "資料・系統整合", "sap": "資料・系統整合",
    "cloud": "資料・系統整合", "api_integration": "資料・系統整合",
    "ai_governance": "AI治理", "agile": "專案管理",
    "solution_architecture": "系統架構", "ai_development": "AI應用開發", "research": "AI應用開發",
    "project_management": "專案管理", "product_management": "專案管理",
    "requirements": "需求分析", "process_diagnosis": "流程優化",
    "change_management": "導入推動", "developer_relations": "導入推動",
    "digital_transformation": "數位轉型",
}


def _to_v3(v2_raw):
    out, seen = [], set()
    for items in v2_raw.values():
        for item in items:
            tag = V2_TO_V3.get(item["tag"])
            if tag and tag not in seen:
                seen.add(tag)
                out.append({"tag": tag, "evidence": item["evidence"]})
    return out


LLM_TAGS = {name: _to_v3(tags) for name, _, _, tags in _ROWS}
JD_TEXTS = {name: text for name, _, text, _ in _ROWS}
PAGE_IDS = {name: pid for name, pid, _, _ in _ROWS}
